return items.map(item => {
  let link = item.json.BinCardLink;

  if (!link || link === "No link provided") {
    return { json: { ...item.json, validImage: false } };
  }

  // Extract file ID
  const match = link.match(/id=([^&]+)/);
  const fileId = match ? match[1] : null;

  if (!fileId) {
    return { json: { ...item.json, validImage: false } };
  }

  const directUrl = `[URL]

  return {
    json: {
      ...item.json,
      validImage: true,
      directImageUrl: directUrl
    }
  };
});

return items.map(item => {
  const link = item.json.BinCardLink;

  return {
    json: {
      ...item.json,
      hasImage: link && link !== "No link provided"
    }
  };
});

const items = $input.all();
const outputItems = [];

for (const item of items) {
  const row = item.json;
  const productDescription = row["Description"];

  if (!productDescription) continue;

  const warehouseRegex = /^(ODL|D-ODL)\d{3}[A-Z]?$/;

  for (const [columnName, value] of Object.entries(row)) {
    if (warehouseRegex.test(columnName)) {
      if (value !== "" && value !== null && value !== undefined) {
        const quantity = Number(value);
        if (!isNaN(quantity) && quantity > 0) {
          outputItems.push({
            json: {
              SKUName:      productDescription,
              WarehouseCode: columnName,
              NAVQuantity:  quantity,
              mergeKey:     `${columnName}__${productDescription}`
            }
          });
        }
      }
    }
  }
}

return outputItems;

const today = new Date();
const todayStr = `${today.getMonth() + 1}/${today.getDate()}/${today.getFullYear()}`;

const allItems = $input.all();

const todayItems = allItems.filter(item => {
  const ts = item.json.Timestamp;
  return ts && ts.split(' ')[0] === todayStr;
});

// Deduplicate by mergeKey — last submission wins
const seen = {};
for (const item of todayItems) {
  const key = `${item.json['Warehouse Number/Name']}__${item.json['S.K.U Name']}`;
  seen[key] = item; // overwrites earlier, so last wins
}

return Object.values(seen).map(item => ({
  json: {
    WarehouseCode: item.json['Warehouse Number/Name'],
    SKUName: item.json['S.K.U Name'].toUpperCase().trim(),
    QuantityCounted: Number(item.json['Quantity Counted']) || 0,
    BinCardLink: item.json['Upload picture of Bin Card'] || null,
    mergeKey: `${item.json['Warehouse Number/Name']}__${item.json['S.K.U Name'].toUpperCase().trim()}`
  }
}));

return items.map(item => {
  let balance = null;
  let binCardStatus = 'PARSE FAILED';

  try {
    const raw = item.json.output;
    const cleaned = raw.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(cleaned);
    balance = parsed.balance !== undefined ? Number(parsed.balance) : null;
    binCardStatus = balance !== null ? 'OK' : 'BALANCE NOT FOUND';
  } catch(e) {
    balance = null;
    binCardStatus = 'PARSE FAILED';
  }

  return {
    json: {
      mergeKey:       item.json.mergeKey,
      BinCardBalance: balance,
      BinCardStatus:  binCardStatus
    }
  };
});

return items.map(item => {
  const physical = item.json.QuantityCounted ?? null;
  const bincard  = item.json.BinCardBalance ?? null;
  const nav      = item.json.NAVQuantity ?? null;
  const binCardStatus = item.json.BinCardStatus ?? 'NO BINCARD UPLOADED';

  const diff = (a, b) => (a !== null && b !== null) ? a - b : null;

  // Boolean comparisons
  const physicalVsBinCard = binCardStatus === 'NO BINCARD UPLOADED'
    ? 'Bin Card Not Recorded'
    : (physical !== null && bincard !== null ? physical === bincard : false);

  const physicalVsNAV = (physical !== null && nav !== null)
    ? physical === nav
    : false;

  const binCardVsNAV = binCardStatus === 'NO BINCARD UPLOADED'
    ? 'Bin Card Not Recorded'
    : (bincard !== null && nav !== null ? bincard === nav : false);

  // Overall status
  let overallStatus;
  const noBinCard = binCardStatus === 'NO BINCARD UPLOADED';
  const physMatchesBin = physicalVsBinCard === true;
  const physMatchesNav = physicalVsNAV === true;
  const binMatchesNav  = binCardVsNAV === true;

  if (physMatchesBin && physMatchesNav && binMatchesNav) {
    overallStatus = 'Fully Balanced';

  } else if (noBinCard && physMatchesNav) {
    overallStatus = 'Partial Balance - Bin Card Not Recorded';

  } else if (noBinCard && !physMatchesNav) {
    overallStatus = 'Total Mismatch - Bin Card Not Recorded ';

  } else if (physMatchesBin && !physMatchesNav) {
    overallStatus = 'Partial Balance - NAV Record Not Matched';

  } else if (physMatchesNav && !physMatchesBin) {
    overallStatus = 'Partial Balance - Bin Card Not Matched';

  } else if (binMatchesNav && !physMatchesBin) {
    overallStatus = 'Partial Balance - Physical Count Not Matched';

  } else {
    overallStatus = 'Total Mismatch';
  }

  return {
    json: {
      Date:                     new Date().toLocaleDateString('en-US'),
      WarehouseCode:            item.json.WarehouseCode,
      SKUName:                  item.json.SKUName,
      PhysicalCount:            physical,
      BinCardBalance:           bincard,
      BinCardStatus:            binCardStatus,
      NAVQuantity:              nav,
      Diff_Physical_vs_BinCard: diff(physical, bincard),
      Diff_Physical_vs_NAV:     diff(physical, nav),
      Diff_BinCard_vs_NAV:      diff(bincard, nav),
      Physical_vs_BinCard:      physicalVsBinCard,
      Physical_vs_NAV:          physicalVsNAV,
      BinCard_vs_NAV:           binCardVsNAV,
      Overall_Status:           overallStatus
    }
  };
});

// All physical entries - the anchor
const physicalItems = $('Extract Today\'s Logs').all();

// Only the entries that had images (same order AI Agent processed them)
const imageItems = $('Tag entries with images').all().filter(i => i.json.hasImage);

// Current input = Parse Bin Card Response output (one per image, same order)
const binCardItems = $input.all();

// Build mergeKey → BinCardBalance map using index alignment
const binCardMap = {};
imageItems.forEach((imgItem, index) => {
  const key = imgItem.json.mergeKey;
  const bc = binCardItems[index];
  if (key && bc) {
    binCardMap[key] = {
      BinCardBalance: bc.json.BinCardBalance ?? null,
      BinCardStatus:  bc.json.BinCardStatus ?? 'PARSE FAILED'
    };
  }
});

// Join every physical entry with its bin card result
return physicalItems.map(item => {
  const key = item.json.mergeKey;
  const bc = binCardMap[key];

  return {
    json: {
      WarehouseCode:   item.json.WarehouseCode,
      SKUName:         item.json.SKUName,
      QuantityCounted: item.json.QuantityCounted,
      mergeKey:        key,
      BinCardBalance:  bc ? bc.BinCardBalance : null,
      BinCardStatus:   bc ? bc.BinCardStatus : 'NO BINCARD UPLOADED'
    }
  };
});
